1	// The constructor keeps the public named param (`repository`) distinct
2	// from the private field it initializes, matching `session_repository_
3	// impl.dart`'s/`auth_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:async';
6	
7	import 'package:fpdart/fpdart.dart';
8	
9	import '../../../../core/failure/failure.dart';
10	import '../entities/entry.dart';
11	import '../entities/pending_entry_write.dart';
12	import '../repositories/entries_repository.dart';
