13	const _entry = Entry(
14	  id: 'server-1',
15	  content: 'Hoje foi um bom dia.',
16	  source: EntrySource.manual,
17	  chatMessageId: null,
18	  occurredAt: '2026-01-01T00:00:00Z',
19	  serverRevision: 1,
20	  createdAt: '2026-01-01T00:00:00Z',
21	  updatedAt: '2026-01-01T00:00:00Z',
22	);
23	
24	/// A scriptable fake `EntriesRepository` — same plain-fake convention
25	/// every other repository-backed cubit test in this codebase already
26	/// uses, needed here because a single test drives several distinct
27	/// `create()` calls (the initial attempt, then a `retry()`) with
28	/// different queued results.
29	class _FakeEntriesRepository implements EntriesRepository {
30	  final List<Completer<Either<Failure, Entry>>> _completers = [];
31	  int createCallCount = 0;
32	  final List<String> createdContents = [];
33	
34	  @override
35	  Future<Either<Failure, Entry>> create({
36	    required String content,
37	    required EntrySource source,
38	    int? mediaDurationSeconds,
39	    String? chatMessageId,
40	  }) {
41	    createCallCount++;
42	    createdContents.add(content);
43	    final completer = Completer<Either<Failure, Entry>>();
44	    _completers.add(completer);
45	    return completer.future;
46	  }
47	
48	  void resolve(int callIndex, Either<Failure, Entry> result) {
49	    _completers[callIndex].complete(result);
50	  }
51	
52	  @override
53	  Future<Either<Failure, EntriesPage>> list({
54	    String? cursor,
55	    int limit = 20,
56	    EntrySource? source,
57	    DateTime? dateFrom,
58	    DateTime? dateTo,
59	  }) async => throw UnimplementedError('not expected to be called');
60	
61	  @override
62	  Future<Either<Failure, Entry>> getById(String id) async =>
63	      throw UnimplementedError('not expected to be called');
64	
65	  @override
66	  Future<Either<Failure, List<Entry>>> search(
67	    String query, {
68	    EntrySource? source,
69	    DateTime? dateFrom,
70	    DateTime? dateTo,
71	  }) async => throw UnimplementedError('not expected to be called');
72	
73	  // Story 8.4 — not exercised by this suite, same trivial rationale this
74	  // fake's other untouched members already follow.
75	  @override
76	  Future<Either<Failure, Unit>> clearLocalCache() async => right(unit);
77	}
78	
79	void main() {
80	  late _FakeEntriesRepository fakeRepository;
81	  late PendingEntryWriteTrackerImpl tracker;
82	
83	  setUp(() {
84	    fakeRepository = _FakeEntriesRepository();
85	    tracker = PendingEntryWriteTrackerImpl(repository: fakeRepository);
86	  });
87	
88	  group('create()', () {
89	    test(
90	      'records an optimistic inFlight PendingEntryWrite before the '
91	      'repository call resolves, visible on pendingWrites immediately',
92	      () async {
93	        final snapshots = <List<PendingEntryWrite>>[];
94	        final subscription = tracker.pendingWrites.listen(snapshots.add);
95	
96	        final createFuture = tracker.create(
97	          content: 'Hoje foi um bom dia.',
98	          source: EntrySource.manual,
99	        );
100	        await Future<void>.delayed(Duration.zero);
101	
102	        expect(snapshots, isNotEmpty);
103	        final latest = snapshots.last;
104	        expect(latest, hasLength(1));
105	        expect(latest.single.content, 'Hoje foi um bom dia.');
106	        expect(latest.single.status, isA<PendingEntryWriteInFlight>());
107	
108	        fakeRepository.resolve(0, right(_entry));
109	        await createFuture;
110	        await subscription.cancel();
111	      },
112	    );
113	
114	    test('identical contract to EntriesRepository.create() — forwards '
115	        'content/source/mediaDurationSeconds verbatim and returns the '
116	        'repository\'s own result', () async {
117	      final createFuture = tracker.create(
118	        content: 'Áudio transcrito.',
119	        source: EntrySource.audio,
120	        mediaDurationSeconds: 7,
121	      );
122	
123	      fakeRepository.resolve(0, right(_entry));
124	      final result = await createFuture;
125	
126	      expect(result, right(_entry));
127	      expect(fakeRepository.createdContents, ['Áudio transcrito.']);
128	    });
129	
130	    test('on success: drops the pending record and broadcasts the confirmed '
131	        'Entry paired with its own tempId on confirmedWrites', () async {
132	      final confirmed = <({String tempId, Entry entry})>[];
133	      final confirmedSubscription = tracker.confirmedWrites.listen(
134	        confirmed.add,
135	      );
136	      final pendingSnapshots = <List<PendingEntryWrite>>[];
137	      final pendingSubscription = tracker.pendingWrites.listen(
138	        pendingSnapshots.add,
139	      );
140	
141	      final createFuture = tracker.create(
142	        content: 'Hoje foi um bom dia.',
143	        source: EntrySource.manual,
144	      );
145	      await Future<void>.delayed(Duration.zero);
146	      expect(pendingSnapshots.last, hasLength(1));
147	      final tempId = pendingSnapshots.last.single.tempId;
