150	/// A controllable `PendingEntryWriteTracker` fake — lets a test drive
151	/// [pendingWrites]/[confirmedWrites] directly (simulating a capture cubit
152	/// elsewhere, sharing the same tracker instance in production) and records
153	/// every [retry] call so `MeusRegistrosCubit.retry()`'s own delegation can
154	/// be asserted without a real `EntriesRepository` behind it.
155	class _FakePendingEntryWriteTracker implements PendingEntryWriteTracker {
156	  final _pendingController =
157	      StreamController<List<PendingEntryWrite>>.broadcast();
158	  final _confirmedController =
159	      StreamController<({String tempId, Entry entry})>.broadcast();
160	  final List<String> retryCalls = [];
161	
162	  void emitPendingWrites(List<PendingEntryWrite> writes) =>
163	      _pendingController.add(writes);
164	
165	  void emitConfirmed(String tempId, Entry entry) =>
166	      _confirmedController.add((tempId: tempId, entry: entry));
167	
168	  @override
169	  Stream<List<PendingEntryWrite>> get pendingWrites =>
170	      _pendingController.stream;
171	
172	  @override
173	  Stream<({String tempId, Entry entry})> get confirmedWrites =>
174	      _confirmedController.stream;
175	
176	  @override
177	  Future<Either<Failure, Entry>> create({
178	    required String content,
179	    required EntrySource source,
180	    int? mediaDurationSeconds,
181	  }) async => throw UnimplementedError('not expected to be called');
182	
183	  @override
184	  Future<void> retry(String tempId) async {
185	    retryCalls.add(tempId);
186	  }
187	
188	  @override
189	  Future<void> dispose() async {
190	    await _pendingController.close();
191	    await _confirmedController.close();
192	  }
193	}
