22	/// Same shape as `entries_list_flow_e2e_test.dart`'s own fake — only the
23	/// transport boundary is faked, everything above it (URL building, both
24	/// real interceptors, `ApiClient`'s mapping) and below it (real `hive_ce`
25	/// write-through) is the genuine production wiring.
26	class _FakeHttpClientAdapter implements HttpClientAdapter {
27	  final List<RequestOptions> requests = [];
28	  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];
29	
30	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
31	    _queue.add((statusCode: statusCode, body: body));
32	  }
33	
34	  void queueErrorResponse(String code, String message) {
35	    queueJsonResponse(503, {
36	      'code': code,
37	      'message': message,
38	      'retryable': true,
39	    });
40	  }
41	
42	  @override
43	  Future<ResponseBody> fetch(
44	    RequestOptions options,
45	    Stream<Uint8List>? requestStream,
46	    Future<void>? cancelFuture,
47	  ) async {
48	    requests.add(options);
49	    if (_queue.isEmpty) {
50	      throw StateError(
51	        'No queued response for ${options.method} ${options.path}',
52	      );
53	    }
54	    final next = _queue.removeAt(0);
55	    return ResponseBody.fromString(
56	      jsonEncode(next.body),
57	      next.statusCode,
58	      headers: {
59	        Headers.contentTypeHeader: [Headers.jsonContentType],
60	      },
61	    );
62	  }
63	
64	  @override
65	  void close({bool force = false}) {}
66	}
