103	  const secureStorageChannel = MethodChannel(
104	    'plugins.it_nomads.com/flutter_secure_storage',
105	  );
106	  final fakeNativeStorage = <String, String>{};
107	
108	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
109	    final args = call.arguments as Map<dynamic, dynamic>;
110	    switch (call.method) {
111	      case 'write':
112	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
113	        return null;
114	      case 'read':
115	        return fakeNativeStorage[args['key'] as String];
116	      case 'delete':
117	        fakeNativeStorage.remove(args['key'] as String);
118	        return null;
119	      case 'containsKey':
120	        return fakeNativeStorage.containsKey(args['key'] as String);
121	      default:
122	        return null;
123	    }
124	  }
