14	/// Drives `EntryDetailScreen` (spec-4-4) — the Boundaries' three-source
15	/// composition, merged only here (AD-7: "it never imports/reaches into
16	/// `MeusRegistrosCubit` or any other Cubit"):
17	/// [SessionRepository.statusStream] (auth status — folded into
18	/// [EntryDetailState.sessionStatus] on every emit, the documented compose
19	/// point the Acceptance Criteria's third bullet names, even though nothing
20	/// this screen renders branches on it today: `ExpiryOverlayHost`'s own
21	/// independent subscription to the same stream, unchanged, is still what
22	/// actually shows the session-expired overlay above this screen,
23	/// Boundaries: "no new overlay"), [PendingEntryWriteTracker.pendingWrites]
24	/// feeding the one shared `deriveSyncBadgeState()` (never recomputed
25	/// inline), and one [EntriesRepository.getById] fetch per [load] call.
26	///
27	/// A DI `factory` (Code Map) — unlike `MeusRegistrosCubit`'s
28	/// `lazySingleton`, a fresh instance per visit to `/meus-registros/:id`
29	/// matches this screen's single-fetch, throwaway lifecycle, mirroring the
30	/// capture cubits' own factory shape (`capture_injection.dart`).
31	class EntryDetailCubit extends Cubit<EntryDetailState> {
32	  EntryDetailCubit(this._repository, this._tracker, this._sessionRepository)
33	    : super(const EntryDetailLoading()) {
34	    _pendingSubscription = _tracker.pendingWrites.listen(
35	      (writes) => _pendingWrites = writes,
36	    );
37	    _sessionSubscription = _sessionRepository.statusStream.listen(
38	      _onSessionStatusChanged,
39	    );
40	  }
41	
42	  final EntriesRepository _repository;
43	  final PendingEntryWriteTracker _tracker;
44	  final SessionRepository _sessionRepository;
45	
46	  late final StreamSubscription<List<PendingEntryWrite>> _pendingSubscription;
47	  late final StreamSubscription<SessionStatus> _sessionSubscription;
48	
49	  /// Mirrors `MeusRegistrosCubit`'s own field of the same name — the
50	  /// tracker's latest snapshot, read synchronously by [load]'s own badge
51	  /// derivation rather than awaiting a fresh stream value.
52	  List<PendingEntryWrite> _pendingWrites = const [];
53	
54	  /// The latest [SessionStatus] this cubit has observed off the composed
55	  /// [SessionRepository.statusStream] — stamped onto every emitted
56	  /// [EntryDetailState] (including a re-emit of the current state below,
57	  /// so a status tick that arrives after [load] has already resolved is
58	  /// still reflected without disturbing the resolved entry/badge data).
59	  SessionStatus? _sessionStatus;
60	
61	  void _onSessionStatusChanged(SessionStatus status) {
62	    _sessionStatus = status;
63	    if (!isClosed) {
64	      emit(_restamped(state, status));
65	    }
66	  }
67	
68	  /// Returns [current] with [status] stamped on, preserving every other
69	  /// field — used both by [_onSessionStatusChanged] (re-emit) and [load]
70	  /// (first emit of each new variant).
71	  EntryDetailState _restamped(
72	    EntryDetailState current,
73	    SessionStatus? status,
74	  ) => switch (current) {
75	    EntryDetailLoading() => EntryDetailLoading(sessionStatus: status),
76	    EntryDetailData(entry: final entry, badgeState: final badgeState) =>
77	      EntryDetailData(
78	        entry: entry,
79	        badgeState: badgeState,
80	        sessionStatus: status,
81	      ),
82	    EntryDetailNotFound() => EntryDetailNotFound(sessionStatus: status),
83	    EntryDetailError(message: final message) => EntryDetailError(
84	      message: message,
85	      sessionStatus: status,
86	    ),
87	  };
88	
89	  /// Guards a stale in-flight [load] call's result landing after a newer
90	  /// one (e.g. a quick back-then-forward re-navigation) — same rationale
91	  /// and shape as `MeusRegistrosCubit._generation`.
92	  int _generation = 0;
93	
94	  /// `EntryDetailScreen`'s one driver, called from the `GoRoute.builder`
95	  /// cascade (Code Map: `sl<EntryDetailCubit>()..load(...)`) — [id] is
96	  /// either a real server id or a still-pending/failed placeholder's
97	  /// synthetic `tempId` (Boundaries: "un-special-cased navigation target");
98	  /// both are simply passed straight through to [EntriesRepository.
99	  /// getById] with no branching here.
100	  Future<void> load(String id) async {
101	    final generation = ++_generation;
102	    emit(EntryDetailLoading(sessionStatus: _sessionStatus));
103	    final result = await _repository.getById(id);
104	    if (isClosed || generation != _generation) {
105	      return;
106	    }
107	    result.match(
108	      (failure) {
109	        if (failure is NotFound) {
110	          emit(EntryDetailNotFound(sessionStatus: _sessionStatus));
111	          return;
112	        }
113	        // Boundaries: every other non-absorbed Failure renders the exact
114	        // same generic not-found treatment `EntryDetailScreen` gives
115	        // EntryDetailNotFound — kept as its own state only for a test's
116	        // sake (entry_detail_state.dart's own doc).
117	        emit(
118	          EntryDetailError(
119	            message: failure.message,
120	            sessionStatus: _sessionStatus,
121	          ),
122	        );
123	      },
124	      (entry) {
125	        PendingEntryWrite? matchingPending;
126	        for (final pending in _pendingWrites) {
127	          if (pending.tempId == entry.id) {
128	            matchingPending = pending;
129	            break;
130	          }
131	        }
132	        emit(
133	          EntryDetailData(
134	            entry: entry,
135	            badgeState: deriveSyncBadgeState(entry, matchingPending),
136	            sessionStatus: _sessionStatus,
137	          ),
138	        );
139	      },
140	    );
141	  }
142	
143	  @override
144	  Future<void> close() async {
145	    await _pendingSubscription.cancel();
146	    await _sessionSubscription.cancel();
147	    return super.close();
148	  }
149	}
